<script>
import BaseComponent from '@primevue/core/basecomponent';
import GalleryStyle from 'primevue/gallery/style';

export default {
    name: 'BaseGallery',
    extends: BaseComponent,
    props: {
        activeIndex: {
            type: Number,
            default: 0
        },
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        },
        fullscreen: {
            type: Boolean,
            default: undefined
        },
        closeOnEscape: {
            type: Boolean,
            default: true
        }
    },
    style: GalleryStyle,
    provide() {
        return {
            $pcGallery: this,
            $parentInstance: this
        };
    }
};
</script>
